package echo

import (
	"crypto/tls"
	"net/http"
	"testing"
)

func TestTmpScheme(t *testing.T) {
	cases := []struct {
		name    string
		headers http.Header
		tls     bool
		want    string
	}{
		{
			name:    "invalid proto falls back to protocol",
			headers: http.Header{HeaderXForwardedProto: []string{"invalid"}, HeaderXForwardedProtocol: []string{"https"}},
			want:    "https",
		},
		{
			name: "all invalid falls back to http",
			headers: http.Header{
				HeaderXForwardedProto:    []string{"invalid"},
				HeaderXForwardedProtocol: []string{"invalid"},
				HeaderXForwardedSsl:      []string{"invalid"},
				HeaderXUrlScheme:         []string{"invalid"},
			},
			want: "http",
		},
		{
			name: "tls",
			tls:  true,
			want: "https",
		},
		{
			name:    "proto https",
			headers: http.Header{HeaderXForwardedProto: []string{"https"}},
			want:    "https",
		},
		{
			name:    "protocol http",
			headers: http.Header{HeaderXForwardedProtocol: []string{"http"}},
			want:    "http",
		},
		{
			name:    "ssl on",
			headers: http.Header{HeaderXForwardedSsl: []string{"on"}},
			want:    "https",
		},
		{
			name:    "url scheme https",
			headers: http.Header{HeaderXUrlScheme: []string{"https"}},
			want:    "https",
		},
		{
			name: "empty",
			want: "http",
		},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			req := &http.Request{Header: tc.headers}
			if tc.headers == nil {
				req.Header = http.Header{}
			}
			if tc.tls {
				req.TLS = &tls.ConnectionState{}
			}
			c := &context{request: req}
			if got := c.Scheme(); got != tc.want {
				t.Errorf("Scheme() = %q, want %q", got, tc.want)
			}
		})
	}
}
EOF
cd /echo && gofmt -l zz_tmp_scheme_test.go; go test -count=1 -run TestTmpScheme -v ./

