import (
	"fmt"
	"net/http"
	"testing"
)

func tryFind(t *testing.T, e *Echo, method, path string) (res string) {
	defer func() {
		if r := recover(); r != nil {
			res = fmt.Sprintf("PANIC: %v", r)
		}
	}()
	c := e.NewContext(nil, nil).(*context)
	e.router.Find(method, path, c)
	if c.handler == nil {
		return "handler=nil"
	}
	err := c.handler(c)
	if err == nil {
		return "err=nil"
	}
	if he, ok := err.(*HTTPError); ok {
		return fmt.Sprintf("code=%d path=%q pnames=%v pvalues=%v", he.Code, c.path, c.pnames, c.pvalues)
	}
	return fmt.Sprintf("err=%v", err)
}

