	fmt.Println("--- POST to GET-only routes")
	for _, p := range []string{"/users/create", "/users/alice/edit", "/", "/static/x"} {
		fmt.Printf("%-28q -> %s\n", p, tryFind(t, e, http.MethodPost, p))
	}
